/* Wayguard service worker (generated by client/build.mjs).
 * - App shell and static assets: cached so the app opens without a signal.
 * - API requests: always network (they contain private data).
 * - Map tiles: never cached here, per the tile provider's usage policy. */
const VERSION = '__VERSION__';
const CACHE = `wayguard-${VERSION}`;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(['/index.html', ...PRECACHE]))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('wayguard-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // tiles and other hosts
  if (url.pathname.startsWith('/api/')) return; // private, always live

  if (request.mode === 'navigate') {
    // Network first so users get the latest version; fall back to the shell.
    event.respondWith(fetch(request).catch(() => caches.match('/index.html')));
    return;
  }
  event.respondWith(
    caches.match(request).then((hit) => hit || fetch(request)),
  );
});
